-- ============================================================================
-- seed_football_questions.sql
-- 295 football questions (109 easy, 117 medium, 69 hard), all in the new "Football"
-- category, each with a "Did you know?" line. They feed Football Challenge.
-- Run AFTER 024_content_quality.sql and 031_football_challenge.sql.
-- Safe to re-run (skips existing question text).
-- Have a reviewer check every fact (see content_reviews/football_review.md), starting with CHECK first rows.
-- ============================================================================

insert into public.categories (name, icon)
select 'Football', '⚽'
where not exists (select 1 from public.categories where name = 'Football');

